ddl.value:
(
				"kind" in ('approve', 'hide', 'remove', 'restore')
				and "previous_state" is not null
			) or (
				"kind" in ('lock_post_targeting', 'unlock_post_targeting')
				and "previous_post_targeting_locked" is not null
			) or (
				"kind" in ('invalidate_license', 'restore_license')
				and "previous_recognition_status" is not null
			) or (
				"kind" = 'reverse'
				and num_nonnulls(
					"previous_state",
					"previous_post_targeting_locked"
				) = 1
			)

(
				"subject_kind" = 'auth' and "auth_user_id" is not null and "realm_id" is null and "realm_relation" is null
			) or (
				"subject_kind" = 'realm' and "auth_user_id" is null and "realm_id" is not null and "realm_relation" is not null
			) or (
				"subject_kind" = 'authenticated' and "auth_user_id" is null and "realm_id" is null and "realm_relation" is null
			)

(
				"resolution" is null and "resolved_at" is null and "resolved_by_auth_user_id" is null
			) or (
				"resolution" is not null and "resolved_at" is not null and "resolved_by_auth_user_id" is not null
			)

(
				"subject_kind" = 'auth' and "auth_user_id" is not null and "realm_id" is null and "realm_relation" is null
			) or (
				"subject_kind" = 'realm' and "auth_user_id" is null and "realm_id" is not null and "realm_relation" is not null
			)

(
				"resolution" is null and "resolved_at" is null and "resolved_by_profile_id" is null and "resolved_by_auth_user_id" is null
			) or (
				"resolution" is not null and "resolved_at" is not null and "resolved_by_profile_id" is not null and "resolved_by_auth_user_id" is not null
			)

(
				(
					"offering_ended_at" is null
					and "offering_ended_by_profile_id" is null
				) or (
					"offering_ended_at" is not null
					and "offering_ended_by_profile_id" is not null
				)
			)

(
				"state" = 'active'::user_account_state_value
				and "note" is null
				and "expires_at" is null
			) or (
				"state" = 'suspended'::user_account_state_value
			) or (
				"state" = 'closed'::user_account_state_value
				and "expires_at" is null
			)
